package com.pratik.imagetap;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.widget.*;import java.io.*;
public class PresetTransferActivity extends Activity {
 private Context dataContext;private boolean exporting,busy,sharing;private int slot;private Uri pending;private PresetArchive.Staged staged;private TextView status;
 static void launch(Activity a,boolean export){a.startActivity(new Intent(a,PresetTransferActivity.class).putExtra("export",export).putExtra("slot",PresetStore.active(a)).putExtra("action",ActionType.selected(a).id));}
 @Override public void onCreate(Bundle state){super.onCreate(state);dataContext=ActionType.scope(getApplicationContext(),ActionType.parse(getIntent().getStringExtra("action")));Ui.window(this);if(TapService.instance!=null)TapService.instance.beginPresetTransfer();exporting=getIntent().getBooleanExtra("export",false);slot=getIntent().getIntExtra("slot",0);LinearLayout body=Ui.column(this);body.setBackgroundColor(Ui.BG);body.setPadding(Ui.dp(this,24),Ui.dp(this,40),Ui.dp(this,24),Ui.dp(this,24));body.addView(Ui.label(this,exporting?"Export preset":"Import preset",26,Ui.CREAM));status=Ui.label(this,"Choose a file location…",14,Ui.MUTED);body.addView(status);setContentView(body);
  if(state!=null){sharing=state.getBoolean("sharing",false);if(sharing)return;String uri=state.getString("pending");if(uri!=null){pending=Uri.parse(uri);process();}return;}Intent picker=new Intent(exporting?Intent.ACTION_CREATE_DOCUMENT:Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(exporting?"application/zip":"*/*");if(exporting)picker.putExtra(Intent.EXTRA_TITLE,PresetStore.name(dataContext,slot).replaceAll("[^\\p{L}\\p{N} _-]","_")+".autobash.zip");else picker.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/zip","application/octet-stream","application/x-zip-compressed"});try{startActivityForResult(picker,1);}catch(ActivityNotFoundException e){error("No file picker is available on this device.");}
 }
 @Override protected void onSaveInstanceState(Bundle b){super.onSaveInstanceState(b);b.putBoolean("sharing",sharing);if(pending!=null)b.putString("pending",pending.toString());}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==2){finish();return;}if(request!=1)return;if(result!=RESULT_OK||data==null||data.getData()==null){finish();return;}pending=data.getData();try{int flags=data.getFlags();boolean read=(flags&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0,write=(flags&Intent.FLAG_GRANT_WRITE_URI_PERMISSION)!=0;if(read&&write)getContentResolver().takePersistableUriPermission(pending,Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_WRITE_URI_PERMISSION);else if(read)getContentResolver().takePersistableUriPermission(pending,Intent.FLAG_GRANT_READ_URI_PERMISSION);else if(write)getContentResolver().takePersistableUriPermission(pending,Intent.FLAG_GRANT_WRITE_URI_PERMISSION);}catch(SecurityException ignored){}process();}
 private void process(){if(busy)return;busy=true;status.setText(exporting?"Writing images and options…":"Validating images and options…");new Thread(()->{try{
   if(exporting){try(OutputStream out=getContentResolver().openOutputStream(pending,"wt")){if(out==null)throw new IOException("Cannot write this file");PresetArchive.exportSlot(dataContext,slot,out);}runOnUiThread(()->{busy=false;if(isDestroyed())return;status.setText("Preset exported.");new AlertDialog.Builder(this).setTitle("Preset exported").setMessage("Share this .autobash.zip file. The recipient can import it from Presets in AutoBash 6.8 or later. The action type travels with the preset.").setPositiveButton("Share file",(d,w)->{Intent share=new Intent(Intent.ACTION_SEND).setType("application/zip").putExtra(Intent.EXTRA_STREAM,pending).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);share.setClipData(ClipData.newRawUri("AutoBash preset",pending));try{sharing=true;startActivityForResult(Intent.createChooser(share,"Share preset"),2);}catch(ActivityNotFoundException e){Toast.makeText(this,"File saved. Share it from your Files app.",Toast.LENGTH_LONG).show();finish();}}).setNegativeButton("Done",(d,w)->finish()).setOnCancelListener(d->finish()).show();});
   }else{PresetArchive.Staged ready;try(InputStream in=getContentResolver().openInputStream(pending)){ready=PresetArchive.stage(dataContext,in);}runOnUiThread(()->{busy=false;if(isDestroyed()||isFinishing()){ready.close();return;}if(staged!=null)staged.close();staged=ready;dataContext=ActionType.scope(getApplicationContext(),ready.action);preview();});}
  }catch(Exception e){runOnUiThread(()->{busy=false;if(!isDestroyed())error(e.getMessage());});}},"preset-transfer").start();}
 private void preview(){status.setText("Ready to import "+staged.count()+" images.");LinearLayout form=Ui.column(this);int pad=Ui.dp(this,20);form.setPadding(pad,pad,pad,pad);form.addView(Ui.label(this,staged.action.label+" · "+staged.name+" · "+staged.count()+" images",18,Ui.CREAM));form.addView(Ui.label(this,"Images, masks, names, source sizes and target areas travel with this preset. Device-wide settings and global regions stay local.\n\nChoose a slot in this action to replace and open:",13,Ui.MUTED));RadioGroup group=new RadioGroup(this);form.addView(group);int[] selected={PresetStore.active(dataContext)};String[] expected=new String[3];for(int i=0;i<3;i++)if(PresetStore.files(PresetStore.folder(dataContext,i)).isEmpty()){selected[0]=i;break;}for(int i=0;i<3;i++){expected[i]=PresetStore.folder(dataContext,i).getName();RadioButton choice=new RadioButton(this);choice.setId(100+i);choice.setText("Slot "+(i+1)+" · "+PresetStore.name(dataContext,i)+" · "+PresetStore.files(PresetStore.folder(dataContext,i)).size()+" images");group.addView(choice);}group.check(100+selected[0]);group.setOnCheckedChangeListener((g,id)->selected[0]=id-100);Ui.polish(form);ScrollView scroll=new ScrollView(this);scroll.addView(form);new AlertDialog.Builder(this).setTitle("Import preset").setView(scroll).setPositiveButton("Replace slot & import",(d,w)->install(selected[0],expected[selected[0]])).setNegativeButton("Cancel",(d,w)->finish()).setOnCancelListener(d->finish()).show();}
 private void install(int target,String expected){busy=true;status.setText("Saving preset…");new Thread(()->{try{PresetArchive.install(dataContext,staged,target,expected);runOnUiThread(()->{busy=false;ActionType.select(this,staged.action);if(TapService.instance!=null)TapService.instance.refreshTargets();if(!isDestroyed()){Toast.makeText(this,"Imported "+staged.count()+" images into slot "+(target+1),Toast.LENGTH_LONG).show();finish();}});}catch(Exception e){runOnUiThread(()->{busy=false;if(isDestroyed())staged.close();else error(e.getMessage());});}},"preset-install").start();}
 private void error(String message){new AlertDialog.Builder(this).setTitle("Preset transfer failed").setMessage(message==null?"Could not read or write this preset.":message).setPositiveButton("Done",(d,w)->finish()).setOnCancelListener(d->finish()).show();}
 @Override public void onBackPressed(){if(busy){Toast.makeText(this,"Finishing file operation…",Toast.LENGTH_SHORT).show();return;}finish();}
 @Override protected void onDestroy(){if(staged!=null&&!busy)staged.close();if(isFinishing()&&TapService.instance!=null)TapService.instance.endPresetTransfer();super.onDestroy();}
}
